INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES ("ミッションねえ……\nちょうどいいや\nどこまで片付けられるか\n賭けをしようじゃないか", -416.5, 1, 0.0, 2.1, "2030/01/01 14:59:59", 3001100, "2024/10/31 12:00:00", 100, 2, "ヤマト", 130011, 3001);
INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES ("他人から言われた任務を\n言われるままにやるなんざ\n性に合わないんだがね……\nま、報酬は貰っとこうか", -416.5, 4, 0.0, 5.68, "2030/01/01 14:59:59", 3001101, "2024/10/31 12:00:00", 101, 2, "ヤマト", 130011, 3001);
INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES ("なんだい？　やれンなら\nとっとと済ませちまいな。\nフブキが早くやることやれ\nってボヤいてたよ。", -416.5, 1, 0.0, 0.0, "2030/01/01 14:59:59", 3001102, "2024/10/31 12:00:00", 102, 1, "ヤマト", 130011, 3001);
INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES ("え～？　ぼくに頼みごと～？\nどうしちゃおっかな～\nちゃんとお願いできたら\n考えてあげよっかな～？", -416.5, 1, 0.0, 0.0, "2030/01/01 14:59:59", 3002100, "2024/10/31 12:00:00", 100, 1, "フブキ", 130211, 3002);
INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES ("ほらほらぁ、これが\n欲しいんでしょ～？\nほんと、しょうがないよね～\nザコおに～いさん♡", -416.5, 1, 0.0, 0.0, "2030/01/01 14:59:59", 3002101, "2024/10/31 12:00:00", 101, 1, "フブキ", 130211, 3002);
INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES ("へえ～、欲しいんだ～？\nぼくのた・い・せ・つ・な・モ・ノ\nあははっ！　なに考えてんの？\nもうへんふしじゃ～んｗ", -416.5, 5, 0.0, 8.53, "2030/01/01 14:59:59", 3002102, "2024/10/31 12:00:00", 102, 2, "フブキ", 130211, 3002);
INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES ("なになに～？　もしかしてまた\nおねだりするつもりなんだ？\nとか言って、ほんとはぼくに\n会いたいだけだったりして～？", -416.5, 7, 0.0, 5.67, "2030/01/01 14:59:59", 3002103, "2024/10/31 12:00:00", 103, 1, "フブキ", 130211, 3002);
INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES ("ザコお兄さんってぇ\n頼み方もワンパなのぉ～？\nもっと必死にならないと\nぼくの心は動かせないよ～？", -416.5, 1, 0.0, 0.0, "2030/01/01 14:59:59", 3002104, "2024/10/31 12:00:00", 104, 1, "フブキ", 130211, 3002);
INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES ("あのさーザコお兄さん、\nな～んか調子乗ってない？\nぼくのこと、なんでもくれる\nチョロいやつとか思ってたりー？", -416.5, 3, 0.0, 0.0, "2030/01/01 14:59:59", 3002300, "2024/10/31 12:00:00", 300, 3, "フブキ", 130211, 3004);
INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES ("ざんね～ん♪\nうざいお兄さんには、もうな～んにもあげませ～ん♡\nほんとなっさけなーい♪\nばいば～い♡", -416.5, 7, 0.0, 0.0, "2030/01/01 14:59:59", 3002400, "2024/10/31 12:00:00", 301, 7, "フブキ", 130211, 3005);
INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES ("きゃはは、ほんと必死～♡\nは～、面白かった。\n笑えたからいいよ～\nそれ、恵んだげる～♪", -416.5, 2, 0.0, 4.4, "2030/01/01 14:59:59", 3003200, "2024/10/31 12:00:00", 200, 1, "フブキ", 130211, 3003);
INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES ("は～、しょうがないな～♡\nザコお兄さんってば\nほんとよわよわで\n情けないよね～ｗ", -416.5, 7, 0.0, 0.0, "2030/01/01 14:59:59", 3003201, "2024/10/31 12:00:00", 201, 7, "フブキ", 130211, 3003);
INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES ("お兄さんってば、ぼくがいないと\nほんとザッコザコだよね～\nもっと感謝しろし～♪", -416.5, 1, 0.0, 5.6, "2030/01/01 14:59:59", 3003202, "2024/10/31 12:00:00", 202, 2, "フブキ", 130211, 3003);
